const dictionaries: Record<AppLanguage, Messages> = { "zh-TW": zhTW, "zh-CN": zhCN, en, ja, ko };

export function translate(language: AppLanguage, key: MessageKey, variables?: Record<string, string | number>) {
  let value = platformMessageOverride(language, key) || dictionaries[language]?.[key] || zhTW[key] || key;
  for (const [name, replacement] of Object.entries(variables || {})) value = value.replaceAll(`{${name}}`, String(replacement));
  return value;
}

export const dayjsLocale: Record<AppLanguage, string> = { "zh-TW": "zh-tw", "zh-CN": "zh-cn", en: "en", ja: "ja", ko: "ko" };

